--!strict
local Players=game:GetService("Players");local player=Players.LocalPlayer;local gui=Instance.new("ScreenGui");gui.Name="LobbyGui";gui.ResetOnSpawn=false;gui.Parent=player.PlayerGui
local button=Instance.new("TextButton");button.Name="OpenModes";button.Position=UDim2.fromScale(.03,.78);button.Size=UDim2.fromScale(.16,.08);button.Text="選擇遊戲模式";button.TextScaled=true;button.BackgroundColor3=Color3.fromRGB(245,165,55);button.Parent=gui;Instance.new("UICorner",button).CornerRadius=UDim.new(.2,0)
button.Activated:Connect(function() local menu=player.PlayerGui:FindFirstChild("ModeSelectionGui");if menu then menu.Enabled=not menu.Enabled end end)
local shop=Instance.new("TextButton");shop.Position=UDim2.fromScale(.03,.88);shop.Size=UDim2.fromScale(.075,.06);shop.Text="商店";shop.TextScaled=true;shop.Parent=gui;shop.Activated:Connect(function()local x=player.PlayerGui:FindFirstChild("ShopGui");if x and x:IsA("ScreenGui")then x.Enabled=not x.Enabled end end)
local inventory=Instance.new("TextButton");inventory.Position=UDim2.fromScale(.115,.88);inventory.Size=UDim2.fromScale(.075,.06);inventory.Text="背包";inventory.TextScaled=true;inventory.Parent=gui;inventory.Activated:Connect(function()local x=player.PlayerGui:FindFirstChild("InventoryGui");if x and x:IsA("ScreenGui")then x.Enabled=not x.Enabled end end)
local folder=game:GetService("ReplicatedStorage"):WaitForChild("Remotes",10);if folder then local state=folder:WaitForChild("ModeStateChanged",10);if state and state:IsA("RemoteEvent") then state.OnClientEvent:Connect(function(d)local visible=d.inLobby==true;button.Visible=visible;shop.Visible=visible;inventory.Visible=visible;if not visible then local s=player.PlayerGui:FindFirstChild("ShopGui");if s and s:IsA("ScreenGui")then s.Enabled=false end;local i=player.PlayerGui:FindFirstChild("InventoryGui");if i and i:IsA("ScreenGui")then i.Enabled=false end end end) end end
